private createRotationMatrix(ax: number, ay: number): Float32Array {
	const out = new Float32Array(16);
	const cx = Math.cos(ax);
	const sx = Math.sin(ax);
	const cy = Math.cos(ay);
	const sy = Math.sin(ay);

	out[0] = cy;
	out[2] = sy;
	out[5] = cx;
	out[6] = -sx;
	out[8] = -sy;
	out[9] = sx * cy;
	out[10] = cx * cy;
	out[15] = 1.0;
	return out;
}

